                    <li key={tag}>{tag}</li>
                  ))}
                </ul>
                <span className="project-read">
                  {sv ? "Läs om projektet" : "Explore the project"}
                  <FiArrowRight aria-hidden="true" />
                </span>
              </div>
            </Link>
          </article>
        ))}
      </div>
    </section>
  );
}

